package com.crm.invoice;
import com.crm.invoice.entity.*;import com.crm.invoice.repository.*;import com.crm.invoice.service.*;import com.crm.security.AuthenticatedUserPrincipal;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.junit.jupiter.api.*;import java.util.*;import java.math.BigDecimal;import java.time.LocalDate;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.junit.jupiter.api.Assertions.*;
class InvoicePresentationPolicyTest {static void role(String role){var a=List.of(new SimpleGrantedAuthority("ROLE_"+role));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new AuthenticatedUserPrincipal(42,"synthetic",a),null,a));}InvoicePresentationRepository templates;InvoiceRepository invoices;InvoiceDocumentRepository documents;InvoicePaymentRepository payments;InvoicePresentationService service;InvoicePresentation template;Invoice row;InvoiceDocument saved;
 @BeforeEach void setup(){role("ADMIN");templates=mock(InvoicePresentationRepository.class);invoices=mock(InvoiceRepository.class);documents=mock(InvoiceDocumentRepository.class);payments=mock(InvoicePaymentRepository.class);service=new InvoicePresentationService(templates,invoices,documents,payments);template=new InvoicePresentation();template.setId(2L);template.setName("Brand");template.setHeader("Header");template.setCompany("Company");template.setFooter("Footer");template.setMentions("User supplied mention");template.setLayout("COMPACT");when(templates.lock(2L)).thenReturn(Optional.of(template));when(templates.findById(2L)).thenReturn(Optional.of(template));when(templates.saveAndFlush(any())).thenAnswer(c->{InvoicePresentation t=c.getArgument(0);t.setId(2L);return t;});row=new Invoice();row.setId(7L);row.setInvoiceNumber("INV-KEEP");row.setCustomerId("101");row.setCurrency("TND");row.setSubtotal(new BigDecimal("100.00"));row.setTotalAmount(new BigDecimal("100.00"));row.setStatus("DRAFT");row.setIssueDate(LocalDate.of(2026,11,7));row.setDueDate(LocalDate.of(2026,12,7));when(invoices.lockById(7L)).thenReturn(Optional.of(row));when(invoices.findById(7L)).thenReturn(Optional.of(row));when(documents.saveAndFlush(any())).thenAnswer(c->{saved=c.getArgument(0);return saved;});when(documents.findById(7L)).thenAnswer(c->Optional.ofNullable(saved));}@AfterEach void clear(){SecurityContextHolder.clearContext();}
 InvoicePresentationService.Input input(){return new InvoicePresentationService.Input("Brand","Header","Company","Footer","Mention","DETAIL");}
 @Test void createsAndEditsUnusedStructuredTemplate(){assertEquals("DETAIL",service.save(null,input()).layout());assertEquals("DETAIL",service.save(2L,input()).layout());}
 @Test void usedTemplatesAreFrozenButCanBeDeactivated(){template.setUsed(true);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.save(2L,input()));assertFalse(service.active(2L,false).active());}
 @Test void issuingSnapshotsPdfAndProtectsAmountsWithoutChangingNumber()throws Exception{row.setNotes("PRIVATE-INTERNAL-NOTE");byte[] bytes=service.issue(7L,2L);assertTrue(row.isIssued());assertTrue(template.isUsed());assertEquals("UNPAID",row.getStatus());assertEquals("INV-KEEP",row.getInvoiceNumber());assertEquals(new BigDecimal("100.00"),row.getTotalAmount());try(var doc=org.apache.pdfbox.Loader.loadPDF(bytes)){String text=new org.apache.pdfbox.text.PDFTextStripper().getText(doc);assertTrue(text.contains("Header"));assertFalse(text.contains("PRIVATE-INTERNAL-NOTE"));assertTrue(text.contains("User supplied mention"));assertTrue(text.contains("100,00"));}verify(documents).saveAndFlush(argThat(d->d.getCreatedBy().equals(42L)&&d.getDigest().length()==64));}
 @Test void repeatedIssueAndReadsReturnExactlyTheSameSnapshotAfterPaymentOrModelDeactivation(){byte[] bytes=service.issue(7L,2L);row.setStatus("PAID");template.setActive(false);assertArrayEquals(bytes,service.issue(7L,2L));assertArrayEquals(bytes,service.snapshot(7L));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.issue(7L,3L));verify(documents,times(1)).saveAndFlush(any());}
 @Test void corruptedSnapshotFailsWithoutRerendering(){service.issue(7L,2L);saved.setContent(new byte[]{1,2});assertThrows(IllegalStateException.class,()->service.snapshot(7L));}
 @Test void legacyDocumentPathIsNotAutomaticallyConverted(){assertNull(service.snapshot(7L));verifyNoInteractions(documents);assertFalse(row.isIssued());}
 @Test void paidArchivedInactiveOrIncompleteInvoicesCannotBeIssued(){row.setArchived(true);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.issue(7L,2L));row.setArchived(false);when(payments.existsByInvoiceId(7L)).thenReturn(true);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.issue(7L,2L));when(payments.existsByInvoiceId(7L)).thenReturn(false);template.setActive(false);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.issue(7L,2L));template.setActive(true);row.setCurrency(null);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.issue(7L,2L));verify(documents,never()).saveAndFlush(any());}
 @Test void logoIsRasterOnlyBoundedAndNormalized()throws Exception{var image=new java.awt.image.BufferedImage(12,8,java.awt.image.BufferedImage.TYPE_INT_RGB);var out=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(image,"png",out);byte[] normalized=service.normalizeLogo(out.toByteArray());assertNotNull(javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(normalized)));assertThrows(IllegalArgumentException.class,()->service.normalizeLogo("<svg/>".getBytes()));assertThrows(IllegalArgumentException.class,()->service.normalizeLogo(new byte[262145]));var large=new java.awt.image.BufferedImage(1001,1000,java.awt.image.BufferedImage.TYPE_INT_RGB);out.reset();javax.imageio.ImageIO.write(large,"png",out);byte[] bytes=out.toByteArray();assertThrows(IllegalArgumentException.class,()->service.normalizeLogo(bytes));}
 @Test void previewIsPlainTextAndDoesNotFreezeOrModifyInvoice(){template.setMentions("<script>alert(1)</script>");byte[] bytes=service.previewInvoice(7L,2L);assertTrue(bytes.length>0);assertFalse(row.isIssued());assertFalse(template.isUsed());verify(documents,never()).saveAndFlush(any());}
 @Test void personalRolesCannotManageOrPreviewTemplates(){for(String role:List.of("CLIENT","EMPLOYEE")){role(role);assertThrows(org.springframework.security.access.AccessDeniedException.class,()->service.preview(2L));}verifyNoInteractions(templates);}
}
